      font-size: 0.9rem;
    }

    .error-banner {
      background: #fef2f2;
      border: 1px solid #fecaca;
      color: #b91c1c;
      padding: 0.75rem 1rem;
      border-radius: 8px;
      margin-bottom: 1rem;
      font-size: 0.85rem;
      display: none;
    }

    .refresh-btn {
      background: #4338ca;
      color: #fff;
      border: none;
      padding: 0.5rem 1rem;
      border-radius: 6px;
      font-size: 0.8rem;
      cursor: pointer;
      font-weight: 500;
      transition: background 0.15s;
    }

    .refresh-btn:hover { background: #3730a3; }
  </style>
</head>
<body>
  <header>
    <h1>HITCO Workforce Dashboard</h1>
    <div style="display: flex; align-items: center; gap: 1rem;">
      <button class="refresh-btn" onclick="loadAll()">Refresh</button>
      <span class="status-badge" id="connStatus">Live</span>
    </div>
  </header>

  <div class="container">
    <div class="error-banner" id="errorBanner"></div>

    <div class="section-title">
      Agents <span class="count" id="agentCount">0</span>
    </div>
    <div class="agent-grid" id="agentGrid">
      <div class="loading-msg">Loading agents...</div>
    </div>

    <div class="section-title">
      Task Board <span class="count" id="taskCount">0</span>
    </div>
    <div class="task-board">
      <div class="task-column col-todo">
        <div class="column-header">
          <span class="column-title">To Do</span>
          <span class="column-count" id="todoCount">0</span>
        </div>
        <div id="todoTasks"></div>
      </div>
      <div class="task-column col-in-progress">
        <div class="column-header">
          <span class="column-title">In Progress</span>
          <span class="column-count" id="inProgressCount">0</span>
        </div>
        <div id="inProgressTasks"></div>
      </div>
      <div class="task-column col-done">
        <div class="column-header">
          <span class="column-title">Done</span>
          <span class="column-count" id="doneCount">0</span>
        </div>
        <div id="doneTasks"></div>
      </div>
    </div>
  </div>

  <script>
    // --- Configuration ---
    const API_BASE = window.location.origin;
    const ENDPOINTS = {
      agents: '/api/agents',
      tasks: '/api/tasks'
    };

    // --- Mock Data (used when API is unavailable) ---
    const MOCK_AGENTS = [
      { id: '1', name: 'Project Manager', role: 'ceo', status: 'running', icon: 'crown', capabilities: 'Hiring, planning, coordination' },
      { id: '2', name: 'Frontend Developer', role: 'engineer', status: 'running', icon: 'sparkles', capabilities: 'UI, HTML, CSS, JavaScript' },
      { id: '3', name: 'Backend Developer', role: 'engineer', status: 'running', icon: 'cog', capabilities: 'Node.js, APIs, databases' },
      { id: '4', name: 'Technical Writer', role: 'engineer', status: 'idle', icon: 'pencil', capabilities: 'Documentation, API docs' }
    ];

    const MOCK_TASKS = [
      { id: 'HIT-1', title: 'Hire your first engineer and create a hiring plan', status: 'done', priority: 'medium', assignee: 'Project Manager' },
      { id: 'HIT-2', title: 'Scaffold Node.js server with core workforce management API', status: 'in_progress', priority: 'high', assignee: 'Backend Developer' },
      { id: 'HIT-3', title: 'Build workforce dashboard UI', status: 'in_progress', priority: 'high', assignee: 'Frontend Developer' },
      { id: 'HIT-4', title: 'Draft initial API documentation', status: 'in_progress', priority: 'medium', assignee: 'Technical Writer' }
    ];

    // --- Icon map ---
    const ICONS = {
      crown: { emoji: '\uD83D\uDC51', bg: '#fef3c7' },
      sparkles: { emoji: '\u2728', bg: '#ede9fe' },
      cog: { emoji: '\u2699\uFE0F', bg: '#dbeafe' },
      pencil: { emoji: '\u270F\uFE0F', bg: '#fce7f3' },
      default: { emoji: '\uD83E\uDD16', bg: '#e0e7ff' }
    };

    // --- Rendering ---
    function renderAgents(agents) {
      const grid = document.getElementById('agentGrid');
      document.getElementById('agentCount').textContent = agents.length;

      if (!agents.length) {
        grid.innerHTML = '<div class="loading-msg">No agents found</div>';
        return;
      }

      grid.innerHTML = agents.map(agent => {
        const icon = ICONS[agent.icon] || ICONS.default;
        const statusClass = 'status-' + (agent.status || 'idle');
        return `
          <div class="agent-card">
            <div class="agent-header">
              <div class="agent-icon" style="background: ${icon.bg}">${icon.emoji}</div>
              <div>
                <div class="agent-name">${esc(agent.name)}</div>
                <div class="agent-role">${esc(agent.role || agent.title || '')}</div>
              </div>
            </div>
            <span class="agent-status ${statusClass}">
              <span class="dot"></span>
              ${esc(agent.status || 'idle')}
            </span>
            ${agent.capabilities ? `<div class="agent-meta">${esc(agent.capabilities)}</div>` : ''}
          </div>
        `;
      }).join('');
    }

    function renderTasks(tasks) {
      const buckets = { todo: [], in_progress: [], done: [] };

      tasks.forEach(task => {
        const status = normalizeStatus(task.status);
        if (buckets[status]) {
          buckets[status].push(task);
        } else {
          buckets.todo.push(task);
        }
      });

      document.getElementById('taskCount').textContent = tasks.length;
      document.getElementById('todoCount').textContent = buckets.todo.length;
      document.getElementById('inProgressCount').textContent = buckets.in_progress.length;
      document.getElementById('doneCount').textContent = buckets.done.length;

      document.getElementById('todoTasks').innerHTML = renderTaskCards(buckets.todo);
      document.getElementById('inProgressTasks').innerHTML = renderTaskCards(buckets.in_progress);
      document.getElementById('doneTasks').innerHTML = renderTaskCards(buckets.done);
    }

    function renderTaskCards(tasks) {
      if (!tasks.length) return '<div class="loading-msg">No tasks</div>';
      return tasks.map(t => `
        <div class="task-card">
          <div class="task-title">${esc(t.title)}</div>
          <div class="task-meta">
            <span class="task-id">${esc(t.id || t.identifier || '')}</span>
            <span class="priority-badge priority-${t.priority || 'medium'}">${esc(t.priority || 'medium')}</span>
          </div>
          ${t.assignee ? `<div class="task-assignee">Assigned: ${esc(t.assignee)}</div>` : ''}
        </div>
      `).join('');
    }

    function normalizeStatus(status) {
      if (!status) return 'todo';
      const s = status.toLowerCase().replace(/[\s-]/g, '_');
      if (s === 'done' || s === 'completed' || s === 'cancelled') return 'done';
      if (s === 'in_progress' || s === 'in_review' || s === 'running') return 'in_progress';
      return 'todo';
    }

    function esc(str) {
      const div = document.createElement('div');
      div.textContent = str;
      return div.innerHTML;
    }

    // --- Data Fetching ---
    async function fetchJSON(url) {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    }

    async function loadAgents() {
      try {
        const agents = await fetchJSON(ENDPOINTS.agents);
        renderAgents(Array.isArray(agents) ? agents : []);
        return true;
      } catch {
        renderAgents(MOCK_AGENTS);
        return false;
      }
    }

    async function loadTasks() {
      try {
        const tasks = await fetchJSON(ENDPOINTS.tasks);
        renderTasks(Array.isArray(tasks) ? tasks : []);
        return true;
      } catch {
        renderTasks(MOCK_TASKS);
        return false;
      }
    }

    async function loadAll() {
      const banner = document.getElementById('errorBanner');
      const badge = document.getElementById('connStatus');

      const [agentsOk, tasksOk] = await Promise.all([loadAgents(), loadTasks()]);

      if (!agentsOk || !tasksOk) {
        banner.textContent = 'Backend API unavailable \u2014 showing mock data. Start the server to see live data.';
        banner.style.display = 'block';
        badge.textContent = 'Mock';
        badge.style.background = '#f59e0b';
      } else {
        banner.style.display = 'none';
        badge.textContent = 'Live';
        badge.style.background = '#16a34a';
      }
    }

    // --- Init ---
    loadAll();
    setInterval(loadAll, 30000);
  </script>
</body>
</html>
